select dict_code, dict_sort, dict_label, dict_value, dict_type, css_class, list_class, is_default, status, remark from sys_dict_data where status = 0
AND dict_code = #{dictCode}
AND dict_value = #{dictValue}
AND dict_type = #{dictType}
AND dict_label LIKE CONCAT(CONCAT('%',#{dictLabel},'%'))
AND dict_label = #{dictLabelEqual}

mapper.insert:
INSERT INTO sys_user_video_habit
    (user_habit_key, habit_value, create_time)
VALUES (#{habitKey}, #{habitValue}, now());

mapper.select:
SELECT DISTINCT t1.record_plan_id,t1.record_plan_name,t1.record_plan_status,t1.start_date,t1.end_date, t1.is_all_day,t1.stream_type,t1.storage_type,t1.storage_day,t1.is_audio, t1.device_code,t1.channel_code,t1.tenant_id,t1.creator, t1.create_time,t1.modifier,t1.update_time,t1.delete_flag, ( case when length(IFNULL(ten.device_name, '')) = 0 then t4.device_name else ten.device_name end ) devName, ( case when length(IFNULL(ten.channel_name, '')) = 0 then t3.channel_name else ten.channel_name end ) channelName, t5.tenant_name,t5.province_id,t5.city_id, (SELECT aa.area_name FROM sys_area aa WHERE aa.area_code = t5.province_id) AS province_name, (SELECT aa.area_name FROM sys_area aa WHERE aa.area_code = t5.city_id) AS city_name, t6.NICK_NAME as creatorName,t7.NICK_NAME as modifierName FROM vm_channel_video_plan_t t1 LEFT JOIN vm_channel_info_t t3 ON t1.channel_code = t3.channel_code and t3.delete_flag = '0' LEFT JOIN vm_device_info_t t4 ON t1.device_code = t4.device_code and t4.delete_flag = '0' inner JOIN sys_tenant_info t5 ON t1.tenant_id = t5.tenant_id LEFT JOIN vm_tenant_device_channel_rel_t ten on t4.device_code = ten.device_code and ten.tenant_id = t1.tenant_id and t3.channel_code = ten.channel_code and ten.industry_code = t1.industry_code and ten.delete_flag='0' LEFT JOIN sys_user t6 ON t1.creator = t6.user_name AND t6.DEL_FLAG = '0' and t6.STATUS = '0' LEFT JOIN sys_user t7 ON t1.modifier = t7.user_name AND t7.DEL_FLAG = '0' and t7.STATUS = '0' LEFT JOIN vm_order_devices d ON t1.device_code = d.device_code AND d.delete_flag = '0' AND d.tenant_id = t1.tenant_id AND d.industry_code = t1.industry_code WHERE t1.delete_flag = '0' and d.ord_status IN ( 0, 1, 2 ) ${dataScope}
AND t1.record_plan_id= #{recordPlanId}
AND t1.device_code LIKE CONCAT('%',#{deviceCode},'%')
AND t1.channel_code LIKE CONCAT('%',#{channelCode},'%')
AND t1.tenant_id = #{customerCode}
AND #{startDate} > t1.start_date
AND t1.end_date > #{endDate}
AND t1.record_plan_id = (select record_plan_id from vm_plan_time_section_t where delete_flag = '0' and #{startTime} > start_time)
AND t1.record_plan_id = (select record_plan_id from vm_plan_time_section_t where delete_flag = '0' and end_time > #{endTime})
AND t5.tenant_name LIKE CONCAT('%',#{tenantName},'%')
AND t5.province_id = #{provinceId}
AND t5.city_id = #{cityId}
AND (t1.tenant_id LIKE CONCAT(CONCAT('%',#{keyword},'%')) OR (t5.tenant_name LIKE CONCAT(CONCAT('%',#{keyword},'%'))))
AND ( case when length(IFNULL(ten.device_name, '')) = 0 then t4.device_name LIKE CONCAT('%',#{devName},'%') else ten.device_name LIKE CONCAT('%',#{devName},'%') end )
AND ( case when length(IFNULL(ten.channel_name, '')) = 0 then t3.channel_name LIKE CONCAT('%',#{channelName},'%') else ten.channel_name LIKE CONCAT('%',#{channelName},'%') end )
AND t1.creator= #{creator}
AND t1.create_time >= #{createTimeStart}
AND #{createTimeEnd} >= t1.create_time
AND t1.modifier= #{modifier}
AND t1.update_time >= #{updateTimeStart}
AND #{updateTimeEnd} >= t1.update_time
AND t1.record_plan_status= #{recordPlanStatusStr}
ORDER BY create_time desc

SELECT
record_plan_id,day_of_week,start_time,end_time,creator,create_time,modifier,update_time,delete_flag,industry_code
FROM
vm_plan_time_section_t
WHERE
1=1


    AND record_plan_id= #{recordPlanId}



    AND delete_flag= #{deleteFlag}


    AND industry_code= #{industryCode}

select patrol_id,patrol_name,device_code,channel_code,tenant_id,creator,create_time creator_date,if_cruise,
start_stop,start_time_period,start_stop_date,order_code
from vm_patrol_info_t where 1 = 1

    AND channel_code= #{channelCode}


    AND device_code= #{deviceCode}


    AND tenant_id= #{customerCode}


    AND patrol_id= #{patrolId}


    AND delete_flag= #{deleteFlag}

